-- v0.272: as estruturas de roteiro e de carrossel da Rebecka entram na biblioteca, e o conteúdo guarda a estrutura e o nível de consciência usados.
-- Aditiva: só insere estruturas que ainda não existem pelo nome. Para desfazer: delete das estruturas com ordem entre 200 e 299 e drop das duas colunas.
alter table public.conteudos add column if not exists estrutura_id uuid references public.content_estruturas(id) on delete set null;
alter table public.conteudos add column if not exists nivel_consciencia text check (nivel_consciencia is null or nivel_consciencia in ('inconsciente', 'problema', 'solucao', 'produto', 'total'));

insert into public.content_estruturas (nome, para_que, formatos, etapas, instrucoes, ordem)
select v.nome, v.para_que, v.formatos, v.etapas::jsonb, v.instrucoes, v.ordem
from (values
  ('Reel · A ferida que vira raciocínio', 'Uma vergonha ou erro real vira o raciocínio de negócio que ficou.', array['reels', 'video', 'stories'],
   '[{"nome":"Detalhe (0 a 5 s)","instrucao":"Um detalhe constrangedor e específico, de preferência com imagem antiga na tela."},{"nome":"Situação (5 a 25 s)","instrucao":"A situação, com gente em volta."},{"nome":"A fala (25 a 35 s)","instrucao":"A fala de alguém que abre a ferida, citada palavra por palavra. Só fala real."},{"nome":"O custo (35 a 50 s)","instrucao":"O custo disso e a decisão que nunca teria sido tomada."},{"nome":"O que mudou (50 a 70 s)","instrucao":"O que mudou, com prova real."},{"nome":"Raciocínio (70 a 80 s)","instrucao":"O raciocínio de negócio que ficou e uma pergunta sobre o negócio de quem assiste."}]',
   'Funciona porque a vulnerabilidade aproxima e a prova impede que vire desabafo. Erro comum: dor genérica. Sem o detalhe, não há história. Só use história que a pessoa contou.', 201),
  ('Reel · A armadilha revelada', 'Mostra que a leitura óbvia de um número ou de uma frase está errada.', array['reels', 'video', 'stories'],
   '[{"nome":"A aparência (0 a 3 s)","instrucao":"Algo que parece uma coisa: um número bonito, um funil elogiado, uma frase que todo mundo repete."},{"nome":"A denúncia (3 a 10 s)","instrucao":"Avisar quem assiste de que caiu na leitura óbvia."},{"nome":"O dado que não fecha (10 a 30 s)","instrucao":"O dado que cria a pergunta: então por que isso aconteceu?"},{"nome":"Causas (30 a 60 s)","instrucao":"No máximo duas causas possíveis, uma de cada vez, como hipótese."},{"nome":"Decisão (60 a 80 s)","instrucao":"A decisão que isso permite e uma pergunta para quem assiste."}]',
   'Funciona porque o público sente a própria leitura sendo corrigida. Separe público, hipótese e o dado que comprovaria. Nunca afirme faturamento, lucro ou erro de ninguém. Número fictício vai marcado. Erro comum: pegadinha sem análise, ou causa dita como certeza.', 202),
  ('Reel · O capítulo com gancho', 'Conta um desfecho curioso em capítulos e abre o próximo.', array['reels', 'video', 'stories'],
   '[{"nome":"Desfecho prometido (0 a 5 s)","instrucao":"O desfecho curioso já prometido na primeira frase."},{"nome":"Obstáculos (5 a 60 s)","instrucao":"Obstáculos em sequência, cada um com objeto e fala concretos."},{"nome":"Conclusão parcial (60 a 75 s)","instrucao":"O que este capítulo ensinou. Todo conteúdo precisa concluir."},{"nome":"Próximo capítulo (75 a 80 s)","instrucao":"A pergunta que abre o próximo. Só se ele existir ou estiver no plano."}]',
   'Funciona porque a pessoa volta para saber o que aconteceu. Erro comum: esticar um assunto só para render episódios.', 203),
  ('Reel · A resposta à crítica', 'Responde a uma objeção real sem se defender e sem ironizar.', array['reels', 'video', 'stories'],
   '[{"nome":"A objeção (0 a 8 s)","instrucao":"A objeção ou crítica, dita como foi ouvida. Só objeção real; o resto é hipótese de ângulo."},{"nome":"O que há de verdade (8 a 20 s)","instrucao":"Admitir o que há de verdade nela, sem se defender."},{"nome":"A resposta (20 a 60 s)","instrucao":"A história ou o raciocínio que responde, com um dilema concreto."},{"nome":"Fecho (60 a 80 s)","instrucao":"A resposta voltando à frase do início e uma pergunta."}]',
   'Funciona porque quem tem a mesma dúvida se sente ouvido antes de ser convencido. Não exponha quem disse. Erro comum: ironizar quem disse.', 204),
  ('Reel · A memória que muda de sentido', 'Uma cena pessoal que, no fim, revela uma ideia que vale para todos.', array['reels', 'video', 'stories'],
   '[{"nome":"Cena (0 a 10 s)","instrucao":"Uma cena sensorial ou uma pergunta estranha."},{"nome":"Tentativa (10 a 30 s)","instrucao":"Uma tentativa simples que dá errado."},{"nome":"Percepção (30 a 50 s)","instrucao":"A percepção de que aquilo era sobre outra coisa."},{"nome":"Para todos (50 a 80 s)","instrucao":"Do pessoal para o que vale para todo mundo. Se a ponte para o negócio forçar, deixe só pessoal."}]',
   'Funciona porque é a parte humana do perfil e aproxima sem pedir nada. Só com história real. Erro comum: virar frase motivacional.', 205),
  ('Carrossel · A troca', 'Hábitos que pararam de funcionar e o que fazer em vez disso.', array['carrossel'],
   '[{"nome":"Capa","instrucao":"O que funcionava e parou de funcionar."},{"nome":"Pares (slides 2 a 6)","instrucao":"De 3 a 6 slides: o hábito de um lado e \"em vez disso\" do outro, com a mesma moldura."},{"nome":"Princípio","instrucao":"No penúltimo ou no último slide, o princípio por trás de todas as trocas."}]',
   'Funciona porque a pessoa se reconhece no hábito antes de ser corrigida. Mostre o raciocínio, sem ensinar a montar nada. Erro comum: lista de dicas sem princípio no fim.', 211),
  ('Carrossel · O caso com tese', 'Um caso do mercado explicado por uma tese, do tipo que se manda para o sócio.', array['carrossel'],
   '[{"nome":"Capa","instrucao":"Dois fatos datados que parecem não combinar."},{"nome":"O que todo mundo viu","instrucao":"Slide 2: o fato atual."},{"nome":"Linha do tempo (slides 3 a 6)","instrucao":"Um momento por slide, com fonte pública."},{"nome":"A tese","instrucao":"Slide 7: a tese em uma frase, escrita como hipótese."},{"nome":"O que o mercado ignora","instrucao":"Slide 8, ligado à tese."},{"nome":"Volta à capa","instrucao":"Slide 9: o fato da capa, agora explicado."},{"nome":"Pergunta","instrucao":"Slide 10: pergunta sobre o negócio de quem lê."}]',
   'Separe público, hipótese e o dado que comprovaria. Nunca afirme faturamento, lucro ou erro de ninguém. Erro comum: biografia sem tese, ou tese que não se aplica a quem lê.', 212),
  ('Carrossel · A história que vira princípio', 'Uma cena real que termina num princípio que a pessoa aplica no negócio.', array['carrossel'],
   '[{"nome":"Capa","instrucao":"A promessa ou o conflito, sem o final."},{"nome":"Cena (slides 2 a 5)","instrucao":"A cena, com gente e fala, um passo por slide. Termina com alguém surpreso ou contrariado."},{"nome":"O nome disso","instrucao":"Slide 6 ou 7: \"e isso tem nome\", ou a passagem da história para o negócio."},{"nome":"Aplicação","instrucao":"Slide 7 ou 8: a aplicação na vida de quem lê."},{"nome":"Fecho","instrucao":"Último: a pergunta ou a conclusão, voltando à cena."}]',
   'Funciona porque o princípio chega depois de a pessoa sentir a história. Sem história real, use fato público com fonte. Erro comum: interromper a cena para explicar.', 213),
  ('Carrossel · O paralelo com refrão', 'A mesma frase-moldura repetida com exemplos novos.', array['carrossel'],
   '[{"nome":"Capa","instrucao":"Já é o primeiro exemplo, sem título explicativo."},{"nome":"Refrão (slides 2 a 5)","instrucao":"A mesma frase-moldura repetida, com um exemplo novo em cada slide."},{"nome":"Conclusão","instrucao":"Último: uma ou duas frases que dão sentido à repetição, ou a pergunta."}]',
   'Precisa de material visual forte, de preferência prints reais. Erro comum: usar quando faltam imagens boas. Nesse caso, avise e sugira outra estrutura.', 214),
  ('Carrossel · A prova em série', 'Vários casos do mesmo tipo levam a uma conclusão que inverte o esperado.', array['carrossel'],
   '[{"nome":"Capa","instrucao":"Já é o primeiro caso, em par: o esforço em cima e o resultado embaixo."},{"nome":"Mais casos (slides 2 a 5)","instrucao":"Mais pares do mesmo tipo, com pessoas ou empresas diferentes e fatos específicos."},{"nome":"Conclusão","instrucao":"Último: a conclusão que inverte o esperado e termina em pergunta."}]',
   'Use casos públicos e conferíveis. Número de página de vendas não é prova. Sem três casos conferíveis, escolha outra estrutura. Erro comum: chamar de prova uma frase motivacional.', 215),
  ('Carrossel · O mito com dados', 'Contraria o que o mercado repete, mostrando os dois lados com dados.', array['carrossel'],
   '[{"nome":"Capa","instrucao":"Uma ordem provocativa, contrária ao que o mercado repete."},{"nome":"O que se ouve","instrucao":"Slide 2: o que se ouve por aí, seguido de \"cuidado\"."},{"nome":"O fato","instrucao":"Slide 3: \"o fato é\", com a prova real na tela."},{"nome":"Os dois lados","instrucao":"Slides 4 e 5: o que cada lado faz bem e faz mal, sem caricatura."},{"nome":"Conclusão","instrucao":"Slide 6: o que se concluiu olhando os números."},{"nome":"Fecho","instrucao":"Último: pergunta ou palavra-chave."}]',
   'A prova tem que ser real ou marcada como simulação. Erro comum: declarar um vencedor universal; a conclusão é que depende do caso.', 216),
  ('Carrossel · A anatomia do fenômeno', 'Explica a lógica por trás de uma moda e leva para o negócio de quem lê.', array['carrossel'],
   '[{"nome":"Capa","instrucao":"Por que [coisa curiosa] está [acontecendo]?, com a promessa de levar a lógica para o caso de quem lê."},{"nome":"O que é","instrucao":"Slide 2: em uma cena que a pessoa já viu."},{"nome":"Por que funciona","instrucao":"Slide 3: 2 ou 3 razões."},{"nome":"A lógica","instrucao":"Slide 4: o ponto não é a moda, é a lógica por trás."},{"nome":"Outros contextos","instrucao":"Slides 5 e 6: a mesma lógica em outros contextos."},{"nome":"Princípio","instrucao":"Slide 7."},{"nome":"Fecho","instrucao":"Último: pergunta ou palavra-chave."}]',
   'Sem passo a passo de ferramenta. Erro comum: explicar a moda e parar, sem chegar à decisão.', 217),
  ('Carrossel · A curadoria comentada', 'Uma coleção com filtro pessoal e opinião em cada item.', array['carrossel'],
   '[{"nome":"Capa","instrucao":"A coleção com um filtro pessoal. Evite \"as melhores\" genérico."},{"nome":"Itens","instrucao":"Um item por slide: nome curto, uma linha do porquê, um exemplo. Mesma ordem em todos."},{"nome":"Fecho","instrucao":"Último: salvar, mandar para alguém, ou palavra-chave."}]',
   'Só como curadoria de sinais, perguntas ou decisões, nunca lista de ferramentas ou formatos para copiar. Erro comum: lista sem opinião.', 218)
) as v(nome, para_que, formatos, etapas, instrucoes, ordem)
where not exists (select 1 from public.content_estruturas e where e.nome = v.nome);

notify pgrst, 'reload schema';
